{-| @Backend.Runtime.Host.Child — programs started and still running, and programs run to their end, as `Pudu.Eval.Child` and `Pudu.Eval.Clock` answer them. -}
module Pudu.Backend.Runtime.Host.Child (hostChildParts) where

import Data.Text (Text)

{-| Each part: its name, the parts it needs, and its lines. -}
hostChildParts :: [(Text, [Text], [Text])]
hostChildParts =
  [ ("host_children", ["host_optional", "host_done", "host_fail", "host_fail_io", "host_grow", "host_gate", "host_path", "kernel_signed", "kernel_int", "memory_failure", "array"],
      [ "#include <fcntl.h>"
      , "#include <poll.h>"
      , "#include <spawn.h>"
      , "#include <sys/wait.h>"
      , "#if !defined(_WIN32)"
      , "extern char **environ;"
      , "#endif"
      , "/* The working directory is set by the spawn itself, under the name the system gives that step. */"
      , "#if defined(__APPLE__) && defined(__MAC_OS_X_VERSION_MIN_REQUIRED) && __MAC_OS_X_VERSION_MIN_REQUIRED >= 260000"
      , "#define PUDU_HOST_SPAWN_CHDIR posix_spawn_file_actions_addchdir"
      , "#else"
      , "#if !defined(__APPLE__)"
      , "extern int posix_spawn_file_actions_addchdir_np(posix_spawn_file_actions_t *actions, const char *path);"
      , "#endif"
      , "#define PUDU_HOST_SPAWN_CHDIR posix_spawn_file_actions_addchdir_np"
      , "#endif"
      , "/* Started programs behind their tokens, numbered from one in their own run."
      , "   A token stays for the whole run. What is written to a program's input is"
      , "   held until 8192 bytes are waiting or the input is closed. */"
      , "typedef struct {"
      , "  pid_t pid;"
      , "  int input, output, errors, input_number, output_number, errors_number, reaped, status;"
      , "  unsigned char *pending;"
      , "  size_t held;"
      , "} pudu_host_child;"
      , "PUDU_OPTIONAL static pudu_host_child *pudu_host_child_table = NULL;"
      , "PUDU_OPTIONAL static size_t pudu_host_child_room = 0;"
      , "PUDU_OPTIONAL static int64_t pudu_host_child_next = 1;"
      , "PUDU_OPTIONAL static inline pudu_host_child *pudu_host_child_find(pudu_int token) {"
      , "  int64_t wanted = pudu_kernel_signed(token.bits);"
      , "  if (wanted < 1 || wanted >= pudu_host_child_next) { pudu_host_fail(\"this token names no started program\"); return NULL; }"
      , "  return &pudu_host_child_table[wanted];"
      , "}"
      , "/* Whatever the run started is asked to stop when the run ends. */"
      , "PUDU_OPTIONAL static void pudu_host_children_end(void) {"
      , "  for (int64_t token = 1; token < pudu_host_child_next; ++token) {"
      , "    pudu_host_child *child = &pudu_host_child_table[token];"
      , "    if (child->input >= 0) (void)close(child->input);"
      , "    if (child->output >= 0) (void)close(child->output);"
      , "    if (child->errors >= 0) (void)close(child->errors);"
      , "    if (!child->reaped) (void)kill(child->pid, SIGTERM);"
      , "    free(child->pending);"
      , "  }"
      , "  free(pudu_host_child_table);"
      , "  pudu_host_child_table = NULL;"
      , "  pudu_host_child_room = 0;"
      , "  pudu_host_child_next = 1;"
      , "}"
      , "PUDU_OPTIONAL static inline void pudu_host_child_settle(pudu_host_child *child, int status) {"
      , "  child->reaped = 1;"
      , "  child->status = WIFEXITED(status) ? WEXITSTATUS(status) : WIFSIGNALED(status) ? -WTERMSIG(status) : 0;"
      , "}"
      , "PUDU_OPTIONAL static inline pudu_text pudu_host_child_named(char *words, size_t room, int descriptor) {"
      , "  pudu_text name;"
      , "  (void)snprintf(words, room, \"fd:%d\", descriptor);"
      , "  name.bytes = (const unsigned char *)words;"
      , "  name.length = strlen(words);"
      , "  name.owner = NULL;"
      , "  return name;"
      , "}"
      , "PUDU_OPTIONAL static inline char *pudu_host_child_word(pudu_text text) { return pudu_host_path(text); }"
      , "/* Starts a program with three pipes: 0 and the parent's ends, or the error number. */"
      , "PUDU_OPTIONAL static inline int pudu_host_child_start(pudu_text program, pudu_box *arguments, pudu_box *variables, int inherits, pudu_text directory, pid_t *pid, int ends[3]) {"
      , "  size_t count = (size_t)pudu_array_length(arguments), given = variables == NULL ? 0 : (size_t)pudu_array_length(variables), inherited = 0, placed = 0;"
      , "  char **words = pudu_host_grow(NULL, (count + 2) * sizeof *words), **around = environ, **made = NULL;"
      , "  char *where = directory.length != 0 ? pudu_host_child_word(directory) : NULL;"
      , "  int pipes[6] = {-1, -1, -1, -1, -1, -1}, code = 0;"
      , "  posix_spawn_file_actions_t actions;"
      , "  words[0] = pudu_host_child_word(program);"
      , "  for (size_t index = 0; index < count; ++index) words[index + 1] = pudu_host_child_word(arguments->fields[0].items->cells[index].text);"
      , "  words[count + 1] = NULL;"
      , "  if (!(inherits && given == 0)) {"
      , "    for (char **entry = environ; inherits && entry != NULL && *entry != NULL; ++entry) inherited += 1;"
      , "    made = pudu_host_grow(NULL, (given + inherited + 1) * sizeof *made);"
      , "    for (size_t index = 0; index < given; ++index) {"
      , "      pudu_box *pair = variables->fields[0].items->cells[index].box;"
      , "      pudu_text name = pair->fields[0].text, value = pair->fields[1].text;"
      , "      char *entry = pudu_host_grow(NULL, name.length + value.length + 2);"
      , "      if (name.length != 0) memcpy(entry, name.bytes, name.length);"
      , "      entry[name.length] = '=';"
      , "      if (value.length != 0) memcpy(entry + name.length + 1, value.bytes, value.length);"
      , "      entry[name.length + 1 + value.length] = 0;"
      , "      made[placed++] = entry;"
      , "    }"
      , "    for (char **entry = environ; inherits && entry != NULL && *entry != NULL; ++entry) {"
      , "      const char *split = strchr(*entry, '=');"
      , "      size_t length = split == NULL ? strlen(*entry) : (size_t)(split - *entry);"
      , "      int overridden = 0;"
      , "      for (size_t index = 0; index < given && !overridden; ++index) {"
      , "        pudu_text name = variables->fields[0].items->cells[index].box->fields[0].text;"
      , "        overridden = name.length == length && memcmp(name.bytes, *entry, length) == 0;"
      , "      }"
      , "      if (!overridden) made[placed++] = *entry;"
      , "    }"
      , "    made[placed] = NULL;"
      , "    around = made;"
      , "  }"
      , "  if (pipe(pipes) != 0 || pipe(pipes + 2) != 0 || pipe(pipes + 4) != 0) code = errno;"
      , "  for (int index = 0; code == 0 && index < 6; ++index) (void)fcntl(pipes[index], F_SETFD, FD_CLOEXEC);"
      , "  if (code == 0) {"
      , "    code = posix_spawn_file_actions_init(&actions);"
      , "    if (code == 0) {"
      , "      if (where != NULL) code = PUDU_HOST_SPAWN_CHDIR(&actions, where);"
      , "      if (code == 0) code = posix_spawn_file_actions_adddup2(&actions, pipes[0], 0);"
      , "      if (code == 0) code = posix_spawn_file_actions_adddup2(&actions, pipes[3], 1);"
      , "      if (code == 0) code = posix_spawn_file_actions_adddup2(&actions, pipes[5], 2);"
      , "      if (code == 0) code = posix_spawnp(pid, words[0], &actions, NULL, words, around);"
      , "      (void)posix_spawn_file_actions_destroy(&actions);"
      , "    }"
      , "  }"
      , "  if (pipes[0] >= 0) (void)close(pipes[0]);"
      , "  if (pipes[3] >= 0) (void)close(pipes[3]);"
      , "  if (pipes[5] >= 0) (void)close(pipes[5]);"
      , "  if (code != 0) {"
      , "    if (pipes[1] >= 0) (void)close(pipes[1]);"
      , "    if (pipes[2] >= 0) (void)close(pipes[2]);"
      , "    if (pipes[4] >= 0) (void)close(pipes[4]);"
      , "  } else {"
      , "    ends[0] = pipes[1];"
      , "    ends[1] = pipes[2];"
      , "    ends[2] = pipes[4];"
      , "    (void)signal(SIGPIPE, SIG_IGN);"
      , "  }"
      , "  for (size_t index = 0; index < given; ++index) free(made[index]);"
      , "  free(made);"
      , "  for (size_t index = 0; index <= count; ++index) free(words[index]);"
      , "  free(words);"
      , "  free(where);"
      , "  return code;"
      , "}"
      , "PUDU_OPTIONAL static inline pudu_int pudu_host_child_keep(pudu_text program, pudu_box *arguments, pudu_box *variables, int inherits, pudu_text directory) {"
      , "  pid_t pid = 0;"
      , "  int ends[3] = {-1, -1, -1};"
      , "  int code = pudu_host_child_start(program, arguments, variables, inherits, directory, &pid, ends);"
      , "  int64_t token;"
      , "  pudu_host_child *child;"
      , "  if (code != 0) { pudu_host_fail_io(program, \"createProcess: posix_spawnp\", code); return pudu_kernel_int(0); }"
      , "  if (pudu_host_child_table == NULL && atexit(pudu_host_children_end) != 0) pudu_memory_failure();"
      , "  token = pudu_host_child_next++;"
      , "  if ((size_t)token >= pudu_host_child_room) {"
      , "    size_t room = pudu_host_child_room < 8 ? 8 : pudu_host_child_room * 2;"
      , "    pudu_host_child_table = pudu_host_grow(pudu_host_child_table, room * sizeof *pudu_host_child_table);"
      , "    pudu_host_child_room = room;"
      , "  }"
      , "  child = &pudu_host_child_table[token];"
      , "  memset(child, 0, sizeof *child);"
      , "  child->pid = pid;"
      , "  child->input = child->input_number = ends[0];"
      , "  child->output = child->output_number = ends[1];"
      , "  child->errors = child->errors_number = ends[2];"
      , "  pudu_host_done(0);"
      , "  return pudu_kernel_int(token);"
      , "}"
      , "/* Every byte through the descriptor while others run, or the error number. */"
      , "PUDU_OPTIONAL static inline int pudu_host_child_push(int descriptor, const unsigned char *bytes, size_t length) {"
      , "  int code = 0;"
      , "  pudu_host_leave();"
      , "  while (length != 0) {"
      , "    ssize_t wrote = write(descriptor, bytes, length);"
      , "    if (wrote < 0) { if (errno == EINTR) continue; code = errno; break; }"
      , "    bytes += wrote;"
      , "    length -= (size_t)wrote;"
      , "  }"
      , "  pudu_host_enter();"
      , "  return code;"
      , "}"
      ])
  , ("host_child_spawn", ["host_children"],
      [ "static pudu_int pudu_host_child_spawn(pudu_text program, pudu_box *arguments) {"
      , "  pudu_text none = {(const unsigned char *)\"\", 0, NULL};"
      , "  return pudu_host_child_keep(program, arguments, NULL, 1, none);"
      , "}"
      ])
  , ("host_child_spawn_with", ["host_children"],
      [ "/* Given variables come first and replace inherited ones of the same name;"
      , "   without inheritance the program sees only what was given. */"
      , "static pudu_int pudu_host_child_spawn_with(pudu_text program, pudu_box *arguments, pudu_box *variables, int inherits, pudu_text directory) {"
      , "  return pudu_host_child_keep(program, arguments, variables, inherits, directory);"
      , "}"
      ])
  , ("host_child_read", ["host_children", "kernel_fresh", "bytes_wrap"],
      [ "/* Stream 0 is what the program wrote, stream 1 what it reported. State 2 when the stream ended. */"
      , "static pudu_box *pudu_host_child_read(pudu_int token, pudu_int count, int stream) {"
      , "  pudu_host_child *child = pudu_host_child_find(token);"
      , "  int64_t wanted = pudu_kernel_signed(count.bits);"
      , "  unsigned char *bytes;"
      , "  pudu_text chunk;"
      , "  ssize_t got;"
      , "  int descriptor, code = 0;"
      , "  char words[32];"
      , "  if (child == NULL) return NULL;"
      , "  if (wanted < 1) { pudu_host_fail(\"a read of no bytes reads nothing\"); return NULL; }"
      , "  descriptor = stream == 0 ? child->output : child->errors;"
      , "  chunk = pudu_kernel_fresh((size_t)wanted, &bytes);"
      , "  pudu_host_leave();"
      , "  do { got = read(descriptor, bytes, (size_t)wanted); } while (got < 0 && errno == EINTR);"
      , "  code = errno;"
      , "  pudu_host_enter();"
      , "  if (got <= 0) pudu_text_release(chunk);"
      , "  if (got < 0) { pudu_host_fail_io(pudu_host_child_named(words, sizeof words, descriptor), \"hGetBufSome\", code); return NULL; }"
      , "  if (got == 0) { pudu_host_done(2); return NULL; }"
      , "  chunk.length = (size_t)got;"
      , "  pudu_host_done(0);"
      , "  return pudu_bytes_wrap(chunk);"
      , "}"
      ])
  , ("host_child_write", ["host_children"],
      [ "static int pudu_host_child_write(pudu_int token, pudu_box *chunk) {"
      , "  pudu_host_child *child = pudu_host_child_find(token);"
      , "  pudu_text bytes = chunk->fields[0].text;"
      , "  char words[32];"
      , "  int code = 0, descriptor;"
      , "  if (child == NULL) return 0;"
      , "  if (bytes.length == 0) { pudu_host_done(0); return 1; }"
      , "  descriptor = child->input;"
      , "  if (descriptor < 0) {"
      , "    pudu_host_fail_reason(pudu_host_child_named(words, sizeof words, child->input_number), \"hPutBuf\", \"illegal operation\", \"handle is closed\");"
      , "    return 0;"
      , "  }"
      , "  if (child->pending == NULL) child->pending = pudu_host_grow(NULL, 8192);"
      , "  if (!(bytes.length < 8192 && bytes.length <= 8192 - child->held)) {"
      , "    unsigned char *waiting = child->pending;"
      , "    size_t held = child->held;"
      , "    child->held = 0;"
      , "    code = pudu_host_child_push(descriptor, waiting, held);"
      , "    if (code == 0 && bytes.length >= 8192) code = pudu_host_child_push(descriptor, bytes.bytes, bytes.length);"
      , "    child = &pudu_host_child_table[pudu_kernel_signed(token.bits)];"
      , "  }"
      , "  if (code == 0 && bytes.length < 8192) {"
      , "    memcpy(child->pending + child->held, bytes.bytes, bytes.length);"
      , "    child->held += bytes.length;"
      , "    if (child->held == 8192) {"
      , "      child->held = 0;"
      , "      code = pudu_host_child_push(descriptor, child->pending, 8192);"
      , "    }"
      , "  }"
      , "  if (code != 0) { pudu_host_fail_io(pudu_host_child_named(words, sizeof words, descriptor), \"hPutBuf\", code); return 0; }"
      , "  pudu_host_done(0);"
      , "  return 1;"
      , "}"
      ])
  , ("host_child_close_input", ["host_children"],
      [ "/* What was waiting is written, then the program is told there is no more. */"
      , "static int pudu_host_child_close_input(pudu_int token) {"
      , "  pudu_host_child *child = pudu_host_child_find(token);"
      , "  char words[32];"
      , "  int code, descriptor;"
      , "  if (child == NULL) return 0;"
      , "  descriptor = child->input;"
      , "  if (descriptor < 0) { pudu_host_done(0); return 1; }"
      , "  child->input = -1;"
      , "  code = pudu_host_child_push(descriptor, child->pending, child->held);"
      , "  child = &pudu_host_child_table[pudu_kernel_signed(token.bits)];"
      , "  child->held = 0;"
      , "  if (close(descriptor) != 0 && code == 0) code = errno;"
      , "  if (code != 0) { pudu_host_fail_io(pudu_host_child_named(words, sizeof words, descriptor), \"hClose\", code); return 0; }"
      , "  pudu_host_done(0);"
      , "  return 1;"
      , "}"
      ])
  , ("host_child_waiting", ["host_children"],
      [ "/* The status a program left: what it exited with, or the signal that ended it, negated. */"
      , "PUDU_OPTIONAL static inline int pudu_host_child_waiting(pudu_int token, int stopping) {"
      , "  pudu_text none = {(const unsigned char *)\"\", 0, NULL};"
      , "  pudu_host_child *child = pudu_host_child_find(token);"
      , "  if (child == NULL) return 0;"
      , "  if (!child->reaped) {"
      , "    pid_t pid = child->pid, got;"
      , "    int status = 0, code;"
      , "    if (stopping) (void)kill(pid, SIGTERM);"
      , "    pudu_host_leave();"
      , "    do { got = waitpid(pid, &status, 0); } while (got < 0 && errno == EINTR);"
      , "    code = errno;"
      , "    pudu_host_enter();"
      , "    child = &pudu_host_child_table[pudu_kernel_signed(token.bits)];"
      , "    if (got < 0 && !child->reaped) { pudu_host_fail_io(none, \"waitForProcess\", code); return 0; }"
      , "    if (got >= 0) pudu_host_child_settle(child, status);"
      , "  }"
      , "  pudu_host_done(0);"
      , "  return 1;"
      , "}"
      ])
  , ("host_child_wait", ["host_child_waiting"],
      [ "static pudu_int pudu_host_child_wait(pudu_int token) {"
      , "  return pudu_kernel_int(pudu_host_child_waiting(token, 0) ? pudu_host_child_table[pudu_kernel_signed(token.bits)].status : 0);"
      , "}"
      ])
  , ("host_child_stop", ["host_child_waiting"],
      [ "/* Asks the program to stop and waits until it is gone. */"
      , "static pudu_int pudu_host_child_stop(pudu_int token) {"
      , "  return pudu_kernel_int(pudu_host_child_waiting(token, 1) ? pudu_host_child_table[pudu_kernel_signed(token.bits)].status : 0);"
      , "}"
      ])
  , ("host_child_wait_within", ["host_children", "host_time"],
      [ "/* Asks every ten milliseconds until the time is spent; state 2 while the program still runs. */"
      , "static pudu_int pudu_host_child_wait_within(pudu_int token, pudu_int within) {"
      , "  pudu_text none = {(const unsigned char *)\"\", 0, NULL};"
      , "  pudu_host_child *child = pudu_host_child_find(token);"
      , "  int64_t remaining = pudu_kernel_signed(within.bits);"
      , "  if (child == NULL) return pudu_kernel_int(0);"
      , "  if (remaining < 0) remaining = 0;"
      , "  for (;;) {"
      , "    struct timespec step = {0, 10000000L};"
      , "    int status = 0;"
      , "    pid_t got;"
      , "    child = &pudu_host_child_table[pudu_kernel_signed(token.bits)];"
      , "    if (child->reaped) break;"
      , "    got = waitpid(child->pid, &status, WNOHANG);"
      , "    if (got < 0) { pudu_host_fail_io(none, \"getProcessExitCode\", errno); return pudu_kernel_int(0); }"
      , "    if (got > 0) { pudu_host_child_settle(child, status); break; }"
      , "    if (remaining <= 0) { pudu_host_done(2); return pudu_kernel_int(0); }"
      , "    pudu_host_leave();"
      , "    (void)nanosleep(&step, NULL);"
      , "    pudu_host_enter();"
      , "    remaining -= 10;"
      , "  }"
      , "  pudu_host_done(0);"
      , "  return pudu_kernel_int(pudu_host_child_table[pudu_kernel_signed(token.bits)].status);"
      , "}"
      ])
  , ("host_run_program", ["host_children", "text_copy"],
      [ "/* Runs a program to its end, feeding it the text and collecting both of its"
      , "   streams: its status, what it wrote and what it reported. */"
      , "static pudu_box *pudu_host_run_program(pudu_text program, pudu_box *arguments, pudu_text fed) {"
      , "  pudu_text none = {(const unsigned char *)\"\", 0, NULL};"
      , "  pid_t pid = 0, got;"
      , "  int ends[3] = {-1, -1, -1}, status = 0, wrong = -1;"
      , "  int code = pudu_host_child_start(program, arguments, NULL, 1, none, &pid, ends);"
      , "  unsigned char *collected[2] = {NULL, NULL};"
      , "  size_t held[2] = {0, 0}, room[2] = {0, 0}, sent = 0;"
      , "  pudu_box *answer;"
      , "  char words[32], reason[64];"
      , "  if (code != 0) { pudu_host_fail_io(program, \"readCreateProcessWithExitCode: posix_spawnp\", code); return NULL; }"
      , "  for (int index = 0; index < 3; ++index) {"
      , "    int flags = fcntl(ends[index], F_GETFL, 0);"
      , "    if (flags >= 0) (void)fcntl(ends[index], F_SETFL, flags | O_NONBLOCK);"
      , "  }"
      , "  pudu_host_leave();"
      , "  if (fed.length == 0) { (void)close(ends[0]); ends[0] = -1; }"
      , "  while (ends[0] >= 0 || ends[1] >= 0 || ends[2] >= 0) {"
      , "    struct pollfd watched[3];"
      , "    for (int index = 0; index < 3; ++index) {"
      , "      watched[index].fd = ends[index];"
      , "      watched[index].events = index == 0 ? POLLOUT : POLLIN;"
      , "      watched[index].revents = 0;"
      , "    }"
      , "    if (poll(watched, 3, -1) < 0) { if (errno == EINTR) continue; break; }"
      , "    if (ends[0] >= 0 && watched[0].revents != 0) {"
      , "      ssize_t wrote = write(ends[0], fed.bytes + sent, fed.length - sent);"
      , "      if (wrote > 0) sent += (size_t)wrote;"
      , "      if ((wrote < 0 && errno != EAGAIN && errno != EWOULDBLOCK && errno != EINTR) || sent == fed.length) { (void)close(ends[0]); ends[0] = -1; }"
      , "    }"
      , "    for (int index = 1; index < 3; ++index) {"
      , "      ssize_t took;"
      , "      if (ends[index] < 0 || watched[index].revents == 0) continue;"
      , "      if (room[index - 1] - held[index - 1] < 4096) {"
      , "        room[index - 1] = room[index - 1] < 4096 ? 8192 : room[index - 1] * 2;"
      , "        collected[index - 1] = pudu_host_grow(collected[index - 1], room[index - 1]);"
      , "      }"
      , "      took = read(ends[index], collected[index - 1] + held[index - 1], room[index - 1] - held[index - 1]);"
      , "      if (took > 0) held[index - 1] += (size_t)took;"
      , "      else if (took == 0 || (errno != EAGAIN && errno != EWOULDBLOCK && errno != EINTR)) { (void)close(ends[index]); ends[index] = -1; }"
      , "    }"
      , "  }"
      , "  for (int index = 0; index < 3; ++index) if (ends[index] >= 0) (void)close(ends[index]);"
      , "  do { got = waitpid(pid, &status, 0); } while (got < 0 && errno == EINTR);"
      , "  pudu_host_enter();"
      , "  for (int index = 0; index < 2 && wrong < 0; ++index) {"
      , "    for (size_t at = 0; at < held[index] && wrong < 0;) {"
      , "      const unsigned char *bytes = collected[index];"
      , "      unsigned char lead = bytes[at], low = 0x80, high = 0xBF;"
      , "      size_t width = 1;"
      , "      int valid = 1;"
      , "      if (lead >= 0x80) {"
      , "        if (lead >= 0xC2 && lead <= 0xDF) width = 2;"
      , "        else if (lead >= 0xE0 && lead <= 0xEF) { width = 3; if (lead == 0xE0) low = 0xA0; if (lead == 0xED) high = 0x9F; }"
      , "        else if (lead >= 0xF0 && lead <= 0xF4) { width = 4; if (lead == 0xF0) low = 0x90; if (lead == 0xF4) high = 0x8F; }"
      , "        else valid = 0;"
      , "        if (valid && (width > held[index] - at || bytes[at + 1] < low || bytes[at + 1] > high)) valid = 0;"
      , "        for (size_t more = 2; valid && more < width; ++more) if (bytes[at + more] < 0x80 || bytes[at + more] > 0xBF) valid = 0;"
      , "      }"
      , "      if (!valid) wrong = (int)lead;"
      , "      at += width;"
      , "    }"
      , "  }"
      , "  if (wrong >= 0) {"
      , "    (void)snprintf(reason, sizeof reason, \"cannot decode byte sequence starting from %d\", wrong);"
      , "    pudu_host_fail_reason(pudu_host_child_named(words, sizeof words, 0), \"hGetContents\", \"invalid argument\", reason);"
      , "    free(collected[0]);"
      , "    free(collected[1]);"
      , "    return NULL;"
      , "  }"
      , "  answer = pudu_box_new(3);"
      , "  answer->fields[0].integer = pudu_kernel_int(got < 0 ? 0 : WIFEXITED(status) ? WEXITSTATUS(status) : WIFSIGNALED(status) ? -WTERMSIG(status) : 0);"
      , "  answer->fields[1].text = pudu_text_copy(collected[0] == NULL ? \"\" : (const char *)collected[0], held[0]);"
      , "  answer->fields[2].text = pudu_text_copy(collected[1] == NULL ? \"\" : (const char *)collected[1], held[1]);"
      , "  free(collected[0]);"
      , "  free(collected[1]);"
      , "  pudu_host_done(0);"
      , "  return answer;"
      , "}"
      ])
  ]
